    "line_status": "Active",
    "roaming_on_line": true,
    "plan_name": "Premium Plan",
    "data_limit_gb": 15,
    "data_used_gb": 15.1,
    "billing_cycle_ends": "2025-02-28"
  },
  "primary_fix_needed": "You’ve exceeded your plan’s data. We can refuel up to 2 GB immediately at $2.00 per GB. This should restore normal unthrottled speeds right away.",
  "options": [
    {
      "option": "Refuel data now",
      "details": "Add 1–2 GB instantly at $2.00/GB (max 2 GB this cycle). Charged to your account."
    },
    {
      "option": "Change plan",
      "details": "Switch to a plan with more monthly data. This is a longer-term solution; it won’t help instantly unless we process a change now. Happy to list available plans if you prefer."
