  "request_confirmation": {
    "prompt": "Would you like me to refuel your line now?",
    "choices": [
      "Add 1 GB for $2.00",
      "Add 2 GB for $4.00"
    ],
    "note": "Maximum refuel this cycle is 2 GB."
  },
  "after_refuel_instructions": {
    "step_1": "Toggle Airplane Mode OFF then ON (wait 10 seconds) and back OFF, or simply reboot your phone. This refreshes the data session.",
    "step_2": "Check the status bar and tell me: signal bars (0–4) and network type (5G/4G/3G).",
    "step_3": "On your phone, ensure Mobile Data is ON and Data Roaming is ON.",
    "step_4": "Preferred network mode: set to 4G/5G (avoid 2G/3G-only).",
    "step_5": "Turn OFF Data Saver (if ON) and disconnect any VPN temporarily.",
    "step_6": "Run a speed test and share the rating/result. We’re aiming for the best possible, ideally excellent, given local coverage."
  },
  "notes": [
    "Roaming is already enabled on your line, so I won’t change that.",
    "Speeds also depend on local French network coverage, but removing the throttle and using 4G/5G settings gives you the best chance to reach excellent speeds."
  ]
}

