messages.content:
{
  "explanation": "Great job turning Airplane Mode off. Right now your phone is on 2G with one signal bar. 2G cannot deliver excellent speeds. Our goal is to switch your phone’s preferred network to 4G/5G and then re-test.",
  "what_we_ll_do": [
    "Change the phone’s network mode to prefer 4G/5G (this is the biggest fix).",
    "Double-check that any data-limiting settings are off.",
    "Re-test your speed."
  ],
  "step_1_set_network_mode_to_4g_5g": {
    "iPhone": [
      "Open Settings > Cellular.",
      "Tap Cellular Data Options.",
      "Tap Voice & Data.",
      "Select 5G Auto (preferred). If 5G isn’t available, select LTE."
    ],
    "Android": [
      "Open Settings > Network & Internet (or Connections) > Mobile network.",
      "Tap Preferred network type (or Network mode).",
      "Select 5G/4G (LTE) preferred. Avoid options that say 2G or 3G only."
    ],
    "tip": "If you’re not sure which menu you see, tell me the exact labels on your screen and I’ll guide you tap-by-tap."
  },
  "step_2_turn_off_data_limits": {
    "iPhone": [
      "Settings > Cellular > Cellular Data Options.",
      "Make sure Low Data Mode is OFF."
    ],
    "Android": [
      "Settings > Network & Internet > Data Saver.",
      "Make sure Data Saver is OFF."
    ],
    "vpn_check": [
      "iPhone: Settings > VPN. Make sure it shows Not Connected.",
      "Android: Settings > Network & Internet > VPN. Make sure it’s Disconnected."
    ]
  },
  "step_3_refresh_signal": [
    "Move closer to a window or higher floor if possible.",
    "Wait 20–30 seconds after changing the network mode to let it reconnect.",
    "Check the top bar again: do you now see 4G/LTE or 5G, and how many bars?"
  ],
  "step_4_speed_test": [
    "Open your browser and go to fast.com.",
    "Wait for the number to finish and share the Download Mbps.",
    "Optional: Tap “Show more info” and share that number too."
  ],
  "if_still_stuck_on_2g_after_step_1": {
    "next_try": [
      "Toggle Mobile Data OFF, wait 10 seconds, then ON again.",
      "Then re-check if it switches to 4G/LTE or 5G and re-run fast.com."
    ],
    "deeper_fix_if_needed": [
      "We can reset your APN (the phone’s network access settings) to default and then reboot. This is safe and often fixes odd connection modes.",
      "I’ll guide you through it if steps above don’t help."
    ]
  },
  "please_reply_with": [
    "Which path you used (iPhone or Android) and what you set for network mode.",
    "What the top bar shows now (2G/3G/4G/LTE/5G and bars).",
    "Your new fast.com download Mbps.",
    "Your ZIP code (optional but helpful)."
  ],
  "reassurance": "These changes won’t delete anything. They simply tell your phone to use faster networks. If anything is confusing, tell me exactly what you see and I’ll guide you one tap at a time."
}

