messages.content:
{
  "summary": "I can help you restore excellent mobile data while you’re roaming in France. We’ll verify your account/line settings (including roaming and data allowance) and optimize your phone’s settings. I’ll guide you step by step and explain why each step matters.",
  "what_i_need_from_you_first": {
    "identify_customer": "Please provide ONE of the following so I can look up your line and check roaming and data usage:",
    "options": [
      "The phone number of the line with the issue (preferred)",
      "Your customer ID",
      "Your full name AND date of birth (YYYY-MM-DD)"
    ],
    "consent": "Do I have your permission to check your line’s roaming status and data usage, and enable roaming on our side if it’s currently off (at no cost)?"
  },
  "quick_context_questions": [
    "Which city/area in France are you currently in?",
    "Does the speed drop everywhere you go, or only in specific places (e.g., indoors vs outdoors)?",
    "When did this start?",
    "Have you seen any messages about reaching your data limit or throttling this month?"
  ],
  "steps_for_you_now_on_the_phone": [
    {
      "step": "Check status bar",
      "what_to_report": "Tell me: (a) signal bars, (b) the network type shown (5G/4G/LTE/3G/2G), and (c) whether you see an airplane icon.",
      "why": "Confirms cellular connectivity and rules out Airplane Mode."
    },
    {
      "step": "Confirm Mobile Data is ON",
      "how": "Settings > Mobile/Cellular Data: ensure the main data switch is ON.",
      "why": "Data must be enabled for internet over cellular."
    },
    {
      "step": "Turn Data Roaming ON",
      "how": "Settings > Cellular/Mobile Data > Cellular Data Options > Data Roaming: turn ON.",
      "why": "Because you’re in France, roaming must be enabled on the device."
    },
    {
      "step": "Set Network Mode to 4G/5G preferred",
      "how": "Settings > Cellular/Mobile Data > Voice & Data/Preferred network type: choose 4G/5G preferred.",
      "why": "Ensures the phone can use the fastest available networks."
    },
    {
      "step": "Disable VPN (if active)",
      "how": "Settings > VPN: disconnect any active VPN.",
      "why": "VPNs can significantly slow data, especially while roaming."
    },
    {
      "step": "Turn OFF Data Saver/Low Data Mode",
      "how": "Settings > Network & Internet (or Cellular) > Data Saver/Low Data Mode: turn OFF.",
      "why": "These modes can make apps feel slow or unresponsive."
    },
    {
      "step": "Quick network refresh",
      "how": "Toggle Airplane Mode ON for 10 seconds, then OFF; wait 30 seconds.",
      "why": "Forces a fresh registration on the roaming network."
    },
    {
      "step": "Run a speed test",
      "how": "Use any speed test app/site over mobile data (not Wi‑Fi) and tell me the result category (very poor/poor/fair/good/excellent).",
      "why": "Confirms current performance and whether changes helped."
    }
  ],
  "what_i_will_do_after_identification": [
    "Verify your line is active and not suspended.",
    "Confirm international roaming is enabled on our side; if not, I will enable it at no cost.",
    "Check your current cycle’s data usage against your plan limit to see if you’ve run out of data.",
    "If you’re out of data, I can add up to 2 GB of refuel data after confirming the price with you."
  ],
  "next": "Please share your line’s phone number (or other ID), your permission to check/enable roaming, and the results of the steps above (status bar details and the speed test rating). I’ll proceed right away."
}

