messages.content:
{
  "reassurance": "Thanks for trying that. I checked your account: your line (555-123-2002) is Active and in good standing, so this looks like a device/network setting issue we can fix. We’ll go step by step, and none of these steps will erase your data or photos.",
  "plan": [
    {
      "step": "Check SIM status (tells us if the phone sees the SIM)",
      "how": [
        "Open Settings on your Android.",
        "Tap Network & Internet (or Connections) > SIMs or Mobile network.",
        "Look for SIM status. It may show Active/Connected, No SIM/Not detected, or Locked/PUK required.",
        "Please tell me exactly what it says."
      ],
      "why": "If the phone can’t see the SIM or it’s locked, you’ll get No Service."
    },
    {
      "step": "Restart the phone",
      "how": [
        "Hold the power button and choose Restart (or Power off, wait 15 seconds, then power on)."
      ],
      "why": "A restart refreshes the network registration. It won’t erase anything."
    },
    {
      "step": "Set preferred network type to 4G/5G",
      "how": [
        "After restart, go to Settings > Network & Internet (or Connections) > Mobile network.",
        "Tap Preferred network type (or Network mode) and choose 4G/5G (may be called LTE/5G Auto or 5G/4G/3G Auto).",
        "Wait 30 seconds and check the top bar again."
      ],
      "why": "If the phone is stuck on an older mode, it may fail to register properly."
    }
  ],
  "if_then_guidance": [
    {
      "condition": "If SIM status shows No SIM/Not detected",
      "action": [
        "Let me know and we’ll reseat the SIM: power off, eject the SIM tray, gently reinsert the SIM flush and in the same orientation, then power on.",
        "Only do this if you’re comfortable; I can walk you through it slowly."
      ]
    },
    {
      "condition": "If SIM status shows Locked or asks for PIN/PUK",
      "action": [
        "Tell me what you see. SIM security needs special handling; we’ll get you to a human agent to assist with PIN/PUK if needed."
      ]
    },
    {
      "condition": "If SIM status is Active but still shows No Service after the steps",
      "action": [
        "We’ll check APN defaults and refresh registration next."
      ]
    }
  ],
  "optional_help_now": {
    "wifi_calling": {
      "note": "This can let you make/receive calls over Wi‑Fi while we fix cellular.",
      "how": [
        "Connect to your home Wi‑Fi.",
        "Open the Phone app > Settings > Calls (or Settings > Network & Internet > Calls & SMS) > Wi‑Fi Calling.",
        "Turn Wi‑Fi Calling ON.",
        "If you don’t see the option, tell me and we’ll skip it."
      ]
    }
  },
  "please_reply_with": [
    "What exactly the SIM status says.",
    "After the restart and network mode change, does the status bar still say No Service or do any signal bars/4G/LTE/5G icons appear?",
    "Whether you were able to enable Wi‑Fi Calling (optional)."
  ],
  "thought_process": "Your line is fine on our side. The fastest path is to confirm the phone detects the SIM, refresh registration with a restart, and ensure the network mode isn’t limiting connection. If the SIM isn’t detected or is locked, we’ll address that specifically; if it’s detected but still no service, we’ll move to APN reset and, if needed, reseating the SIM."
}

