          "do": "set_network_mode_preference",
          "parameters": { "mode": "4g_5g_preferred" },
          "why": "Ensures the phone can use 4G/5G for higher speeds."
        }
      },
      {
        "action": "check_data_restriction_status",
        "what_to_share": "Whether Data Saver is ON.",
        "if_needed_fix": {
          "condition": "If Data Saver is ON",
          "do": "toggle_data_saver_mode",
          "parameters": { "enabled": false },
          "why": "Data Saver can slow apps and background connectivity."
        }
      },
      {
        "action": "check_vpn_status",
        "what_to_share": "If a VPN is connected.",
        "if_needed_fix": {
          "condition": "If VPN is connected and speeds are poor",
          "do": "disconnect_vpn",
          "why": "Some VPNs severely slow roaming data."
        }
      },
      {
        "action": "check_network_status",
        "if_needed_fix": {
          "condition": "If Mobile Data is OFF",
          "do": "toggle_data",
          "parameters": { "enabled": true },
          "why": "Mobile data must be ON to use the internet."
        }
      },
      {
        "action": "check_network_status",
        "if_needed_fix": {
          "condition": "If Data Roaming is OFF",
          "do": "toggle_roaming",
          "parameters": { "enabled": true },
          "why": "Roaming must be ON when abroad."
        }
      },
      {
        "action": "check_status_bar",
        "if_needed_fix": {
          "condition": "If ✈️ Airplane Mode is ON",
          "do": "toggle_airplane_mode",
          "parameters": { "enabled": false },
          "why": "Airplane Mode blocks all cellular data."
        }
      },
      {
        "action": "check_apn_settings",
        "what_to_share": "Whether APN is marked incorrect.",
        "if_needed_fix": {
          "condition": "If APN is incorrect",
          "do": "reset_apn_settings",
          "followed_by": "reboot_device",
          "why": "Incorrect APN can cause no data or very slow speeds."
        }
      },
      {
        "action": "run_speed_test",
        "preconditions": "Ensure Wi‑Fi is OFF so this measures mobile data.",
        "what_to_share": "The result category (unknown/very poor/poor/fair/good/excellent). Our goal is excellent."
      }
