    },
    {
      "step": "If Airplane Mode is OFF but still no bars",
      "how": [
        "Check Cellular/Mobile Data is ON: Settings > Cellular/Mobile Data > ON.",
        "Check SIM status: Settings > About/Status > SIM status. Tell me what it shows (Active, Missing, Locked). If it shows Missing and you use a physical SIM, power off, remove and reinsert the SIM, then power on."
      ]
    }
