  "acknowledgement": "Thanks for sticking with me—I know this is frustrating. Given your results, the most likely blocker now is the Messaging app missing the storage permission, which MMS needs to access photos/videos.",
  "what_we_found": {
    "data_status": "OK (refueled and working on 5G)",
    "mmsc_apn": "OK",
    "wifi_calling": "OFF",
    "data_saver": "OFF",
    "vpn": "OFF",
    "mms_capability_check": "Fail",
    "app_permissions": {
      "sms": "Granted",
      "phone": "Granted",
      "storage": "Missing"
    }
  },
  "next_steps": [
    {
      "step": 1,
      "action": "Grant Storage permission to the Messaging app",
      "how_to_do_it": [
        "Run: grant_app_permission(app_name=\"messaging\", permission=\"storage\")",
        "Alternatively via settings: Settings > Apps > Messages > Permissions > Allow Storage (or Photos and videos)"
      ],
      "why": "MMS needs access to your media storage to attach and send images/videos."
    },
    {
      "step": 2,
      "action": "Test MMS",
      "how_to_do_it": [
        "Open your Messages app and try sending a picture again."
      ],
      "after_this": "If it still fails, continue to Step 3."
    },
    {
      "step": 3,
      "action": "Quick reset of radio/data sessions",
      "how_to_do_it": [
        "Run: toggle_airplane_mode(ON), wait 10 seconds, then toggle_airplane_mode(OFF).",
        "Run: toggle_data(OFF), wait 5 seconds, then toggle_data(ON)."
      ],
      "why": "This refreshes the network and MMS session without a full reboot.",
      "after_this": "Try sending the MMS again."
    },
    {
      "step": 4,
      "action": "Confirm MMS capability and app background data",
      "how_to_do_it": [
        "Run: can_send_mms and share the result.",
        "Run: check_app_status(app_name=\"messaging\") and tell me if background data is restricted for the app."
      ],
      "why": "MMS can be blocked if the app is restricted from using data in the background."
    },
    {
      "step": 5,
      "action": "Network mode sanity check (optional)",
      "how_to_do_it": [
        "Run: check_network_mode_preference.",
        "If it’s not already 4g_5g_preferred, run: set_network_mode_preference(\"4g_5g_preferred\")."
      ],
      "why": "Ensures the device uses modern networks suitable for MMS."
    }
  ],
  "what_to_report_back": [
    "Confirm that you granted Storage permission.",
    "Whether the MMS sent after Step 2 or Step 3.",
    "The outputs of can_send_mms and check_app_status(app_name=\"messaging\") if you reach Step 4.",
    "Your current network mode if you check it."
  ],
  "reassurance": "Once Storage permission is granted, MMS usually starts working immediately. If it still doesn’t after these steps, I’ll escalate to a human specialist for deeper diagnostics."
}

