      "step": "Turn OFF Data Saver",
      "how": [
        "Settings > Network & Internet > Data Saver > OFF",
        "Samsung: Settings > Connections > Data usage > Data saver > OFF"
      ],
      "reason": "Data Saver can block background data MMS needs."
    },
    {
      "step": "Disconnect any VPN",
