messages.content:
{
  "message": "Great job turning Airplane Mode off. Since MMS still fails, we’ll go step-by-step on Android to isolate and fix what’s blocking picture messages. Nothing below deletes your photos or personal data.",
  "thought_process": "MMS needs working mobile data plus correct MMS/APN settings and app permissions. You now have 5G and data ON, so first we’ll confirm web access over mobile data. If that works, we’ll address settings that commonly block MMS: Wi‑Fi Calling, app permissions, and (if needed) reset APN to restore the MMSC server.",
  "steps": [
    {
      "title": "Quick test: confirm mobile data works",
      "why": "If mobile web works, we know the connection is fine and can focus on MMS-specific settings.",
      "actions": [
        "Open Chrome.",
        "Type example.com and tap Go.",
        "Tell me if the page loads."
      ],
      "expected": "example.com should load over mobile data."
    },
    {
      "title": "Turn OFF Wi‑Fi Calling (just for this test)",
      "why": "Wi‑Fi Calling can sometimes interfere with MMS on some devices.",
      "actions": [
        "Open Settings.",
        "Go to Network & internet (or Connections) > Mobile network (or SIMs).",
        "Find Wi‑Fi Calling and toggle it OFF.",
        "If you can’t find it there: Settings > Apps > Phone (or your dialer app) > Wi‑Fi Calling > turn OFF."
      ],
      "expected": "Wi‑Fi Calling shows as OFF."
    },
    {
      "title": "Check Messages app permissions",
      "why": "The Messages app must have SMS and media (photos/videos/storage) permissions to send MMS.",
      "actions": [
        "Open Settings > Apps > See all apps > Messages (or your messaging app).",
        "Tap Permissions.",
        "Make sure these are Allowed: SMS (or “Send and view SMS/MMS”), and Photos and videos (or Files and media/Storage).",
        "If any are missing, allow them."
      ],
      "expected": "SMS and Photos/Videos (Storage) are allowed."
    },
    {
      "title": "Try sending one photo again",
      "why": "See if MMS works after the above adjustments.",
      "actions": [
        "Open Messages, attach one small photo, and send.",
        "Tell me exactly what happens (sends or “Message not sent”)."
      ]
    }
  ],
  "next_if_still_fails": {
    "title": "Reset APN to restore MMS server (MMSC), then reboot",
    "why": "Incorrect or missing MMSC in APN is a common MMS blocker. Resetting APN restores the correct defaults.",
    "actions": [
      "Open Settings > Network & internet (or Connections) > Mobile network (or SIMs).",
      "Tap Access Point Names (APN).",
      "Tap the three‑dot menu (or More) > Reset to default (or Restore default settings). Confirm.",
      "Now fully restart your phone (power off, wait 10 seconds, power on).",
      "After the reboot, ensure Mobile data is ON and Wi‑Fi is still OFF, then try sending a photo again."
    ],
    "note": "Resetting APN only changes network access settings; it does not erase personal data."
  },
  "questions": [
    "Did example.com load over mobile data?",
    "After turning Wi‑Fi Calling OFF and confirming Messages has SMS and Photos/Videos permissions, does the picture message send?",
    "If not, are you comfortable resetting the APN and rebooting now? I can stay with you through it."
  ]
}

