messages.content:
{
  "thought_process": "Great—now that the SIM is detected, the next blockers are that your phone is locked to 2G and data roaming is OFF. MMS won’t work on 2G. We’ll switch the network mode to 4G/5G and enable roaming on the phone, then test data and MMS.",
  "do_this_next_on_your_android": [
    {
      "step": "Set preferred network to 4G/5G",
      "paths": [
        "Settings > Network & Internet (or Connections) > Mobile network > Preferred network type (or Network mode) > choose 5G/4G/3G/2G (auto) or 5G/4G preferred.",
        "On Samsung: Settings > Connections > Mobile networks > Network mode > select 5G/LTE/3G/2G (auto connect)."
      ],
      "notes": "Avoid 2G-only. If you see separate options, pick the highest that includes 4G/LTE (or 5G if available)."
    },
    {
      "step": "Enable Data Roaming",
      "path": "Settings > Network & Internet (or Connections) > Mobile network > Data roaming > ON",
      "notes": "You may see a warning; enabling is required to use data while abroad. Roaming is already enabled on your line on our side."
    },
    {
      "step": "Force a quick re-registration",
      "path": "Toggle Airplane Mode ON for ~10 seconds, then OFF",
      "notes": "This refreshes the network connection after changing modes."
    },
    {
      "step": "Test on mobile data only",
      "actions": [
        "Turn Wi‑Fi OFF (and Wi‑Fi Calling OFF if available) temporarily.",
        "Wait 30–60 seconds and check the status bar: you should see 4G/LTE or 5G with some signal bars."
      ]
    }
  ],
  "then_test": [
    "Open a webpage in your browser with Wi‑Fi OFF. Confirm it loads.",
    "Try sending an MMS (a photo) to any contact."
  ],
  "if_it_still_sticks_on_2g_or_mms_fails": [
    "Check Data Saver is OFF: Settings > Network & Internet > Data Saver.",
    "If you use a VPN, disconnect it and retry.",
    "Reset APN to defaults to refresh MMSC settings (for MMS), then reboot: Settings > Network & Internet > Mobile network > Access Point Names > Menu (⋮) > Reset to default, then restart the phone. After reboot, keep Wi‑Fi OFF for the test and try web + MMS again."
  ],
  "please_report_back": [
    "After changing settings, what network type now shows (e.g., 4G/LTE/5G)?",
    "Were you able to load a webpage with Wi‑Fi OFF?",
    "Did the MMS send, or what message do you see now?"
  ]
}

