messages.content:
{
  "thought_process": "Great progress—your SIM is detected and you have strong 5G data. When data works but MMS fails, the usual culprits are APN/MMSC settings, Wi‑Fi Calling interference, Data Saver/VPN, or missing messaging app permissions. We’ll fix those in order.",
  "do_this_next": [
    {
      "step": "Turn off Wi‑Fi and Wi‑Fi Calling for the test",
      "why": "Some setups block MMS over Wi‑Fi.",
      "path": [
        "Turn Wi‑Fi OFF from Quick Settings.",
        "Settings > Network & Internet (or Connections) > Wi‑Fi Calling > turn OFF."
      ]
    },
    {
      "step": "Make sure Data Saver and any VPN are OFF",
      "path": [
        "Settings > Network & Internet > Data Saver > OFF.",
        "Settings > Network & Internet > VPN > Disconnect (if any)."
      ]
    },
    {
      "step": "Reset APN to defaults, then reboot",
      "why": "MMS depends on the MMSC URL in the APN. Resetting restores the correct values.",
      "path": [
        "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names.",
        "Tap the menu (⋮) > Reset to default.",
        "Restart the phone."
      ],
      "after_reboot": [
        "Keep Wi‑Fi OFF.",
        "Confirm you still have 4G/5G signal and data works by loading a webpage.",
        "Try sending an MMS again."
      ]
    },
    {
      "step": "Check messaging app permissions (if MMS still fails)",
      "why": "The app needs access to media and SMS to send MMS.",
      "path": [
        "Settings > Apps > Your messaging app (e.g., Messages).",
        "Permissions > ensure Photos and videos (or Storage) = Allow, and SMS = Allow.",
        "Mobile data & Wi‑Fi (or Data usage) > Allow background data and, if available, Unrestricted data usage."
      ],
      "retry": "Open a webpage to verify mobile data, then send an MMS again."
    }
  ],
  "please_report_back": [
    "After the APN reset and reboot, were you able to load a webpage with Wi‑Fi OFF?",
    "Did the MMS send successfully, or what message do you see now?",
    "If it still fails, confirm Wi‑Fi Calling is OFF and list which permissions your messaging app shows as Allowed."
  ],
  "notes": [
    "Roaming is already enabled on your line on our side.",
    "If you see APN options you’re unsure about, you can just Reset to default—no custom entries needed.",
    "If after these steps MMS still won’t send, we’ll run one more check together and I’ll escalate if needed."
  ]
}

