messages.content:
{
  "thought_process": "Your line now has active data again (we added 2 GB), so MMS should work as long as your phone is allowed to use mobile data while roaming and its MMS settings are correct. Since SMS/calls work, we’ll focus on device-side causes that most commonly block MMS abroad: mobile data/roaming toggles on the phone, Wi‑Fi Calling interference, APN/MMSC settings, unsuitable network mode (e.g., 2G), Data Saver/VPN restrictions, or missing app permissions. I’ll have you run quick checks and apply targeted fixes based on what you see.",
  "step_by_step_checks": [
    {
      "title": "Confirm phone is using mobile data while roaming",
      "why": "MMS requires mobile data, even when you have Wi‑Fi. Being abroad, you must have both Mobile Data and Data Roaming turned ON on the phone.",
      "do": [
        "Run check_network_status and share the results (signal strength, network type, Mobile Data ON/OFF, Data Roaming ON/OFF)."
      ],
      "if_then": [
        "If Mobile Data is OFF: use toggle_data to turn it ON.",
        "If Data Roaming is OFF: use toggle_roaming to turn it ON."
      ],
      "test": "After turning these ON (if they were OFF), try sending an MMS again."
    },
    {
      "title": "Rule out Wi‑Fi Calling conflicts",
      "why": "Some configurations interfere with MMS, especially when abroad.",
      "do": [
        "Run check_wifi_calling_status and share the result."
      ],
      "if_then": [
        "If Wi‑Fi Calling is ON: use toggle_wifi_calling to turn it OFF."
      ],
      "test": "Try sending an MMS again after turning Wi‑Fi Calling OFF."
    },
    {
      "title": "Verify APN and MMSC settings",
      "why": "Incorrect/missing MMSC prevents MMS from sending.",
      "do": [
        "Run check_apn_settings and share the APN name and MMSC URL you see."
      ],
      "if_then": [
        "If the MMSC URL is missing or looks incorrect: use reset_apn_settings to restore defaults, then use reboot_device to restart the phone."
      ],
      "test": "After reboot, try sending an MMS again."
    },
    {
      "title": "Ensure network mode allows 4G/5G",
      "why": "2G/3G can break MMS; 4G/5G is recommended.",
      "do": [
        "Run check_network_mode_preference and share the result."
      ],
      "if_then": [
        "If it shows 2G or 3G: use set_network_mode_preference with mode \"4g_5g_preferred\"."
      ],
      "test": "Try sending an MMS again."
    },
    {
      "title": "Disable Data Saver and any VPN",
      "why": "Data Saver or a slow/misconfigured VPN can block or slow MMS.",
      "do": [
        "Run check_data_restriction_status and share if Data Saver is ON.",
        "Run check_vpn_status and share if a VPN is connected."
      ],
      "if_then": [
        "If Data Saver is ON: use toggle_data_saver_mode to turn it OFF.",
        "If a VPN is connected: use disconnect_vpn to turn it OFF."
      ],
      "test": "Try sending an MMS again."
    },
    {
      "title": "Confirm the messaging app can send MMS and has permissions",
      "why": "The app must be allowed to send MMS and access storage for attachments.",
      "do": [
        "Run can_send_mms and share the result.",
        "Run check_app_permissions with app_name=\"messaging\" and share whether storage and sms permissions are granted."
      ],
      "if_then": [
        "If storage is not granted: use grant_app_permission with permission=\"storage\".",
        "If sms is not granted: use grant_app_permission with permission=\"sms\"."
      ],
      "test": "Try sending an MMS again."
    }
    ],
  "what_to_reply_with": [
    "Results of check_network_status (including Mobile Data and Data Roaming ON/OFF).",
    "Results of check_wifi_calling_status.",
    "APN name and MMSC URL from check_apn_settings.",
    "Network mode from check_network_mode_preference.",
    "Data Saver and VPN status from check_data_restriction_status and check_vpn_status.",
    "Results of can_send_mms and the messaging app permissions (storage and sms) from check_app_permissions."
  ],
  "extra_tip": "While testing, try to keep Wi‑Fi Calling OFF. If MMS still fails after the steps above, let me know each result and I’ll advise the exact next action based on your outputs."
}

