messages.content:
{
  "message": "Great progress—your SIM is now active, you’ve got strong 5G signal, mobile data and roaming are ON, and Wi‑Fi/Wi‑Fi Calling are OFF. Since MMS still hangs, the next most common cause is APN/MMSC configuration or device-side restrictions. We’ll verify that your phone can pass mobile data and then fix MMS-specific settings.",
  "do_this_next_in_order": [
    {
      "step": 1,
      "action": "Verify mobile data actually works (with Wi‑Fi OFF).",
      "how": "Open your browser and load a few websites (e.g., example.com, news site).",
      "expected": "Pages should load quickly on 5G.",
      "why": "MMS requires working mobile data."
    },
    {
      "step": 2,
      "action": "Check and reset APN/MMSC settings, then reboot.",
      "how": [
        "Go to Settings > Network & Internet (or Connections) > Mobile network > Access Point Names (APN).",
        "Tap the active carrier APN. Look for a field named MMSC. If it’s blank or you’re unsure, proceed to reset.",
        "Use the menu (⋮) in the APN screen > Reset to default.",
        "After resetting, fully restart the phone."
      ],
      "why": "A missing/incorrect MMSC URL is a top reason MMS hangs. Resetting APN restores correct defaults."
    },
    {
      "step": 3,
      "action": "After reboot, re-check key toggles, then test MMS.",
      "how": [
        "Confirm: Mobile Data ON, Data Roaming ON, Wi‑Fi OFF, Wi‑Fi Calling OFF, Preferred network 4G/5G.",
        "Toggle Mobile Data OFF, wait 5 seconds, then ON.",
        "Send a small test MMS (e.g., a photo to your own number)."
      ]
    },
    {
      "step": 4,
      "action": "If it still hangs, rule out data restrictions and VPN.",
      "how": [
        "Data Saver: Settings > Network & Internet > Data Saver > turn OFF.",
        "Per‑app data: Settings > Apps > Messages > Mobile data & Wi‑Fi > enable Background data and Unrestricted data.",
        "VPN: Settings > Network & Internet > VPN > if connected, Disconnect."
      ],
      "why": "Data Saver, per‑app restrictions, or an active VPN can block or stall MMS."
    },
    {
      "step": 5,
      "action": "Confirm Messages app permissions.",
      "how": "Settings > Apps > Messages > Permissions > allow SMS (or Phone/SMS as listed) and Photos/Media/Storage.",
      "why": "The app needs access to send/attach media."
    },
    {
      "step": 6,
      "action": "Test MMS again.",
      "how": "Send a small photo to your own number with Wi‑Fi still OFF."
    }
  ],
  "why_these_steps": "You now have service and data. If MMS still hangs, APN (especially the MMSC URL) is the most common culprit. After that, device data restrictions or app permissions can block MMS traffic.",
  "request": "Please do steps 1–3 first and tell me: (a) could you browse websites on mobile data, (b) whether you reset APN and rebooted, and (c) what happens when you try sending an MMS after reboot. If it still hangs, proceed with steps 4–5 and share what you find."
}

